/* @autogenerated */
package net.civeira.phylax.integrationtest.features.oauth.scenario;

import java.time.Instant;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;

import io.quarkus.arc.profile.IfBuildProfile;
import jakarta.annotation.Priority;
import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.inject.Alternative;
import net.civeira.phylax.features.oauth.authentication.domain.AuthRequest;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationChallenge;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationData;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationMode;
import net.civeira.phylax.features.oauth.authentication.domain.AuthenticationResult;
import net.civeira.phylax.features.oauth.client.domain.ClientDetails;
import net.civeira.phylax.features.oauth.user.domain.gateway.LoginGateway;
import net.civeira.phylax.integrationtest.features.oauth.fixtures.OidcTestFixtures;

@IfBuildProfile("test")
@Alternative
@Priority(1)
@ApplicationScoped
public class ScenarioLoginGateway implements LoginGateway {
  private Supplier<AuthenticationResult> onValidate =
      () -> AuthenticationResult.right(defaultData());
  private Supplier<AuthenticationResult> onPreAuth =
      () -> AuthenticationResult.right(defaultData());

  public void whenValidate(Supplier<AuthenticationResult> behavior) {
    this.onValidate = behavior;
  }

  public void whenPreAuth(Supplier<AuthenticationResult> behavior) {
    this.onPreAuth = behavior;
  }

  /**
   * Resource owner credential checks, the step where roles are computed for the audiences.
   */
  private final AtomicInteger validations = new AtomicInteger();

  public void reset() {
    onValidate = () -> AuthenticationResult.right(defaultData());
    onPreAuth = () -> AuthenticationResult.right(defaultData());
    validations.set(0);
  }

  public int validations() {
    return validations.get();
  }

  @Override
  public AuthenticationResult validateUserData(AuthRequest request, String username,
      String password, ClientDetails client, List<AuthenticationChallenge> challenges) {
    validations.incrementAndGet();
    return withMode(withAudiences(onValidate.get(), request), AuthenticationMode.PASSWORD);
  }

  @Override
  public AuthenticationResult validatePreAuthenticated(AuthRequest request, String username,
      ClientDetails client, List<AuthenticationChallenge> challenges, AuthenticationMode mode) {
    return withMode(withAudiences(onPreAuth.get(), request), mode);
  }

  /**
   * Like UserLoginService, the data says how this call authenticated: its mode, now, and the
   * methods that mode proves by itself.
   */
  private static AuthenticationResult withMode(AuthenticationResult result,
      AuthenticationMode mode) {
    if (result.isRight()) {
      result.getData().setMode(mode);
      result.getData().setTime(Instant.now());
      result.getData().setAmr(new java.util.ArrayList<>(mode.amr()));
    }
    return result;
  }

  /**
   * Like UserLoginService, the granted data carries the audiences of the request.
   */
  private static AuthenticationResult withAudiences(AuthenticationResult result,
      AuthRequest request) {
    if (result.isRight() && request != null && result.getData().getAudiences().isEmpty()) {
      result.getData().setAudiences(request.getAudiences());
    }
    return result;
  }

  private static AuthenticationData defaultData() {
    AuthenticationData data = new AuthenticationData();
    data.setUid("user-1");
    data.setUsername(OidcTestFixtures.USERNAME);
    data.setTenant(OidcTestFixtures.TENANT);
    data.setMode(AuthenticationMode.PASSWORD);
    data.setTime(Instant.now());
    return data;
  }
}
